(function(){
 const select=document.querySelector('[data-language]'); if(!select)return;
 const supported=Object.keys(LANGS);
 let lang='en';
 try { const savedLanguage=localStorage.getItem('portfolio-language'); if(savedLanguage && Object.prototype.hasOwnProperty.call(LANGS,savedLanguage))lang=savedLanguage; else { localStorage.removeItem('portfolio-language'); } } catch(e) {}
 select.innerHTML=supported.map(k=>`<option value="${k}">${LANGS[k]}</option>`).join('');
 select.value=lang;
 function applyLanguage(code){if(!Object.prototype.hasOwnProperty.call(LANGS,code))code='en';lang=code; try { localStorage.setItem('portfolio-language',code); } catch(e) {} document.documentElement.lang=code; document.documentElement.dir=code==='fa'?'rtl':'ltr'; document.body.dir=code==='fa'?'rtl':'ltr';
   const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT); const nodes=[]; while(walker.nextNode())nodes.push(walker.currentNode);
   for(const node of nodes){const original=node.__originalText||node.nodeValue;const key=original.trim(); if(!key)continue; if(!node.__originalText)node.__originalText=original; if(code==='en'){node.nodeValue=original;continue;} const entry=TRANSLATIONS[key];node.nodeValue=(entry&&entry[code])?original.replace(key,entry[code]):original; }
   document.querySelectorAll('[data-language]').forEach(el=>el.value=code);
   document.querySelectorAll('[data-count]').forEach(el=>{if(el.dataset.counterDone==='true'){const locale=code==='fa'?'fa-IR':code==='hi'?'hi-IN':code==='nl'?'nl-NL':code==='de-AT'?'de-AT':code==='de'?'de-DE':'en-US';el.textContent=new Intl.NumberFormat(locale).format(Number(el.dataset.count)||0);}});
   document.querySelectorAll('a[data-en]').forEach(a=>{const key=a.getAttribute('data-en');if(TRANSLATIONS[key]?.[code])a.setAttribute('aria-label',TRANSLATIONS[key][code]);});
 }
 // Store original text once, so language changes don't translate a translation.
 const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(w.nextNode()){w.currentNode.__originalText=w.currentNode.nodeValue;}
 applyLanguage(lang); document.documentElement.classList.add('i18n-ready'); select.addEventListener('change',()=>{applyLanguage(select.value);});
 document.querySelectorAll('[data-count]').forEach(el=>{const target=Number(el.dataset.count)||0;el.textContent='0';el.dataset.counterDone='false';const runCounter=()=>{if(el.dataset.counterDone==='true')return;el.dataset.counterDone='true';const duration=1800;const start=performance.now();const fmt=n=>new Intl.NumberFormat(lang==='fa'?'fa-IR':lang==='hi'?'hi-IN':'en-US').format(n);function frame(now){const t=Math.min(1,(now-start)/duration);const eased=1-Math.pow(1-t,4);el.textContent=fmt(Math.round(target*eased));if(t<1)requestAnimationFrame(frame);}requestAnimationFrame(frame);};if('IntersectionObserver'in window){const counterObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){runCounter();counterObserver.disconnect();}}),{threshold:.35});counterObserver.observe(el);}else runCounter();});
 // Theme preference defaults to light on first visit; saved preference applies afterward.
 const themeButton=document.querySelector('[data-theme-toggle]');const themeIcon=document.querySelector('[data-theme-icon]');let savedTheme=null;try{savedTheme=localStorage.getItem('portfolio-theme')}catch(e){}document.documentElement.dataset.theme=savedTheme==='dark'?'dark':'light';if(themeIcon)themeIcon.textContent=savedTheme==='dark'?'☾':'☼';if(themeButton)themeButton.setAttribute('aria-label',savedTheme==='dark'?'Switch to light mode':'Switch to dark mode');
 if(themeButton)themeButton.addEventListener('click',()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('portfolio-theme',dark?'dark':'light')}catch(e){}if(themeIcon)themeIcon.textContent=dark?'☾':'☼';themeButton.setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');});
 // Native smooth scrolling for in-page anchors; respects reduced-motion preferences.
 document.documentElement.style.scrollBehavior=window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
 const revealEls=document.querySelectorAll('main section, .skill-card, .project-card, .job-card, .stat'); revealEls.forEach((el,i)=>{el.classList.add('reveal');});
 if('IntersectionObserver' in window){const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target);}}),{threshold:.08});revealEls.forEach(el=>io.observe(el));}else revealEls.forEach(el=>el.classList.add('visible'));
 const year=document.getElementById('year');if(year)year.textContent=new Date().getFullYear();
 // Deterrent only: does not prevent saving source, screenshots, or access through developer tools.
 document.addEventListener('contextmenu',e=>e.preventDefault());
 document.addEventListener('dragstart',e=>{if(e.target.tagName==='IMG')e.preventDefault();});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&['s','u'].includes(e.key.toLowerCase()))e.preventDefault();});
 // Smooth, slightly slower transitions between local pages.
 document.querySelectorAll('a[href]').forEach(link=>{const href=link.getAttribute('href');if(!href||href.startsWith('#')||href.startsWith('mailto:')||href.startsWith('tel:')||link.target==='_blank'||link.origin!==location.origin||!href.endsWith('.html'))return;link.addEventListener('click',e=>{if(e.defaultPrevented||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();document.documentElement.classList.add('page-leaving');window.setTimeout(()=>{location.href=link.href;},320);});});
 // A one-time, polished intro on the home/contact page; never delays every navigation.
 if(/(?:^|\/)index\.html$/.test(location.pathname)||location.pathname.endsWith('/')){let seen=false;try{seen=sessionStorage.getItem('portfolio-intro-seen')==='1';}catch(e){}if(!seen){try{sessionStorage.setItem('portfolio-intro-seen','1')}catch(e){}const intro=document.createElement('div');intro.className='portfolio-intro';intro.setAttribute('role','status');intro.setAttribute('aria-label','Welcome');intro.innerHTML='<div class="intro-mark">MS<span>.</span></div><div class="intro-name">MAHMOOD SAHEBI</div><div class="intro-role">NETWORKS · WIRELESS · AUTOMATION</div><div class="intro-track"><span></span></div>';document.body.appendChild(intro);window.setTimeout(()=>{intro.classList.add('intro-dismiss');window.setTimeout(()=>intro.remove(),650);},1450);}}
})();
